package goratelimiter

import (
	"sync"
	"time"
)

type Limiter struct {
	capacity float64
	rate     float64
	tokens   float64
	last     time.Time
	mu       sync.Mutex
}

func New(capacity, rate float64) *Limiter {
	return &Limiter{capacity: capacity, rate: rate, tokens: capacity, last: time.Now()}
}

func (l *Limiter) Allow(n float64) bool {
	l.mu.Lock()
	defer l.mu.Unlock()
	now := time.Now()
	elapsed := now.Sub(l.last).Seconds()
	l.tokens += elapsed * l.rate
	if l.tokens > l.capacity {
		l.tokens = l.capacity
	}
	l.last = now
	if l.tokens < n {
		return false
	}
	l.tokens -= n
	return true
}

