package goratelimiter

import (
	"sync"
	"testing"
	"time"
)

func TestAllow(t *testing.T) {
	tests := []struct {
		name string
		cap  float64
		rate float64
		n    float64
		want bool
	}{
		{"burst within capacity", 5, 1, 5, true},
		{"insufficient", 1, 1, 5, false},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			l := New(tt.cap, tt.rate)
			if got := l.Allow(tt.n); got != tt.want {
				t.Fatalf("Allow(%v)=%v want %v", tt.n, got, tt.want)
			}
		})
	}
}

func TestAllowInsufficientConsumesNothing(t *testing.T) {
	l := New(5, 0)
	if l.Allow(10) {
		t.Fatal("insufficient tokens must not be consumed")
	}
	if !l.Allow(5) {
		t.Fatal("tokens should be intact after a refused Allow")
	}
}

func TestRefill(t *testing.T) {
	l := New(1, 1000)
	l.Allow(1)
	time.Sleep(10 * time.Millisecond)
	if !l.Allow(1) {
		t.Fatal("tokens should refill over time")
	}
}

func TestConcurrent(t *testing.T) {
	l := New(1000, 0)
	var wg sync.WaitGroup
	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func() { defer wg.Done(); l.Allow(1) }()
	}
	wg.Wait()
}

